         </div>\\n            <div class=\\"speedscope-row\\">\\n                <iframe id=\\"speedscopeFrame\\" sandbox=\\"allow-scripts allow-same-origin\\"/>\\n            </div>\\n\\n            <script>\\n                // --- DATA FROM SERVER ---\\n                const memoryData = JSON.parse(atob('<t t-esc=\\"memory_data\\"/>'));\\n                const fullSpeedscopeBase64 = '<t t-esc=\\"speedscope_base64\\"/>';\\n                const cdn = '<t t-esc=\\"cdn\\"/>';\\n                const points = memoryData.points;\\n\\n                // --- UTILITY ---\\n                function formatBytes(bytes) {\\n                    if (bytes === 0) return '0 B';\\n                    const k = 1024;\\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\\n                    const sign = bytes &lt; 0 ? '-' : '';\\n                    return sign + (Math.abs(bytes) / Math.pow(k, i)).toFixed(1) + ' ' + sizes[i];\\n                }\\n\\n                function formatTimestamp(ts) {\\n                    return new Date(ts * 1000).toLocaleTimeString();\\n                }\\n\\n                // --- SPEEDSCOPE IFRAME ---\\n                let currentBlobUrl = null;\\n\\n                function loadSpeedscopeInIframe(base64Data) {\\n                    if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);\\n\\n                    const html = '\\\\x3c!DOCTYPE html\\\\x3e' +\\n                        '\\\\x3chtml\\\\x3e\\\\x3chead\\\\x3e' +\\n                        '\\\\x3cscript\\\\x3ewindow.location.hash=\\"#localProfilePath=1\\";\\\\x3c/script\\\\x3e' +\\n                        '\\\\x3clink href=\\"https://fonts.googleapis.com/css?family=Source+Code+Pro\\" rel=\\"stylesheet\\"/\\\\x3e' +\\n                        '\\\\x3clink rel=\\"stylesheet\\" href=\\"' + cdn + 'reset.8c46b7a1.css\\"/\\\\x3e' +\\n                        '\\\\x3c/head\\\\x3e\\\\x3cbody\\\\x3e' +\\n                        '\\\\x3cscript src=\\"' + cdn + 'speedscope.026f36b0.js\\"\\\\x3e\\\\x3c/script\\\\x3e' +\\n                        '\\\\x3cscript\\\\x3e' +\\n                        'document.addEventListener(\\"DOMContentLoaded\\", function() {' +\\n                        '  speedscope.loadFileFromBase64(\\"Profile\\", \\"' + base64Data + '\\");' +\\n                        '});' +\\n                        '\\\\x3c/script\\\\x3e' +\\n                        '\\\\x3c/body\\\\x3e\\\\x3c/html\\\\x3e';\\n\\n                    const blob = new Blob([html], {type: 'text/html'});\\n                    currentBlobUrl = URL.createObjectURL(blob);\\n                    document.getElementById('speedscopeFrame').src = currentBlobUrl;\\n                }\\n\\n                // --- CHART (hover-only, no click interaction) ---\\n                const labels = points.map(p =&gt; formatTimestamp(p.timestamp));\\n                const memValues = points.map(p =&gt; p.memory);\\n\\n                new Chart(document.getElementById('memoryChart'), {\\n                    type: 'line',\\n                    data: {\\n                        labels: labels,\\n                        datasets: [{\\n                            label: 'RSS Memory (baselined)',\\n                            data: memValues,\\n                            fill: true,\\n                            backgroundColor: 'rgba(75, 192, 192, 0.1)',\\n                            borderColor: 'rgba(75, 192, 192, 1)',\\n                            tension: 0.1,\\n                            pointRadius: 2,\\n                            pointBackgroundColor: 'rgba(75, 192, 192, 1)',\\n                        }]\\n                    },\\n                    options: {\\n                        responsive: true,\\n                        maintainAspectRatio: false,\\n                        plugins: {\\n                            title: { display: true, text: 'RSS Memory Over Time' },\\n                            tooltip: {\\n                                callbacks: {\\n                                    label: ctx =&gt; 'Δ ' + formatBytes(ctx.raw),\\n                                    afterLabel: ctx =&gt; 'Absolute: ' + formatBytes(points[ctx.dataIndex].abs_memory),\\n                                }\\n                            },\\n                            legend: { display: false },\\n                        },\\n                        scales: {\\n                            y: {\\n                                title: { display: true, text: 'Memory (Δ from baseline)' },\\n                                ticks: { callback: v =&gt; formatBytes(v) },\\n                            },\\n                            x: {\\n                                title: { display: true, text: 'Time' },\\n                                ticks: { maxTicksLimit: 20 },\\n                            }\\n                        }\\n                    }\\n                });\\n\\n                // Load full memory speedscope\\n                loadSpeedscopeInIframe(fullSpeedscopeBase64);\\n            </script>\\n        </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.view_memory">\n        &lt;!DOCTYPE html&gt;\n        <html lang="en">\n        <head>\n            <meta charset="UTF-8"/>\n            <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n            <title>Memory Usage Visualization</title>\n            <script src="https://cdn.jsdelivr.net/npm/chart.js"/>\n            <style>\n                * { box-sizing: border-box; margin: 0; padding: 0; }\n                body {\n                    font-family: Arial, sans-serif;\n                    background-color: #f9f9f9;\n                    height: 100vh;\n                    display: flex;\n                    flex-direction: column;\n                }\n                .chart-row {\n                    height: 30vh;\n                    min-height: 200px;\n                    padding: 10px;\n                    flex-shrink: 0;\n                }\n                .chart-container {\n                    position: relative;\n                    background: #fff;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                    padding: 10px;\n                    height: 100%;\n                    width: 100%;\n                }\n                .speedscope-row {\n                    flex: 1;\n                    min-height: 0;\n                    padding: 0 10px 10px;\n                }\n                .speedscope-row iframe {\n                    width: 100%;\n                    height: 100%;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                }\n            </style>\n        </head>\n        <body>\n            <div class="chart-row">\n                <div class="chart-container">\n                    <canvas id="memoryChart"/>\n                </div>\n            </div>\n            <div class="speedscope-row">\n                <iframe id="speedscopeFrame" sandbox="allow-scripts allow-same-origin"/>\n            </div>\n\n            <script>\n                // --- DATA FROM SERVER ---\n                const memoryData = JSON.parse(atob('<t t-esc="memory_data"/>'));\n                const fullSpeedscopeBase64 = '<t t-esc="speedscope_base64"/>';\n                const cdn = '<t t-esc="cdn"/>';\n                const points = memoryData.points;\n\n                // --- UTILITY ---\n                function formatBytes(bytes) {\n                    if (bytes === 0) return '0 B';\n                    const k = 1024;\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\n                    const sign = bytes &lt; 0 ? '-' : '';\n                    return sign + (Math.abs(bytes) / Math.pow(k, i)).toFixed(1) + ' ' + sizes[i];\n                }\n\n                function formatTimestamp(ts) {\n                    return new Date(ts * 1000).toLocaleTimeString();\n                }\n\n                // --- SPEEDSCOPE IFRAME ---\n                let currentBlobUrl = null;\n\n                function loadSpeedscopeInIframe(base64Data) {\n                    if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);\n\n                    const html = '\\x3c!DOCTYPE html\\x3e' +\n                        '\\x3chtml\\x3e\\x3chead\\x3e' +\n                        '\\x3cscript\\x3ewindow.location.hash="#localProfilePath=1";\\x3c/script\\x3e' +\n                        '\\x3clink href="https://fonts.googleapis.com/css?family=Source+Code+Pro" rel="stylesheet"/\\x3e' +\n                        '\\x3clink rel="stylesheet" href="' + cdn + 'reset.8c46b7a1.css"/\\x3e' +\n                        '\\x3c/head\\x3e\\x3cbody\\x3e' +\n                        '\\x3cscript src="' + cdn + 'speedscope.026f36b0.js"\\x3e\\x3c/script\\x3e' +\n                        '\\x3cscript\\x3e' +\n                        'document.addEventListener("DOMContentLoaded", function() {' +\n                        '  speedscope.loadFileFromBase64("Profile", "' + base64Data + '");' +\n                        '});' +\n                        '\\x3c/script\\x3e' +\n                        '\\x3c/body\\x3e\\x3c/html\\x3e';\n\n                    const blob = new Blob([html], {type: 'text/html'});\n                    currentBlobUrl = URL.createObjectURL(blob);\n                    document.getElementById('speedscopeFrame').src = currentBlobUrl;\n                }\n\n                // --- CHART (hover-only, no click interaction) ---\n                const labels = points.map(p =&gt; formatTimestamp(p.timestamp));\n                const memValues = points.map(p =&gt; p.memory);\n\n                new Chart(document.getElementById('memoryChart'), {\n                    type: 'line',\n                    data: {\n                        labels: labels,\n                        datasets: [{\n                            label: 'RSS Memory (baselined)',\n                            data: memValues,\n                            fill: true,\n                            backgroundColor: 'rgba(75, 192, 192, 0.1)',\n                            borderColor: 'rgba(75, 192, 192, 1)',\n                            tension: 0.1,\n                            pointRadius: 2,\n                            pointBackgroundColor: 'rgba(75, 192, 192, 1)',\n                        }]\n                    },\n                    options: {\n                        responsive: true,\n                        maintainAspectRatio: false,\n                        plugins: {\n                            title: { display: true, text: 'RSS Memory Over Time' },\n                            tooltip: {\n                                callbacks: {\n                                    label: ctx =&gt; 'Δ ' + formatBytes(ctx.raw),\n                                    afterLabel: ctx =&gt; 'Absolute: ' + formatBytes(points[ctx.dataIndex].abs_memory),\n                                }\n                            },\n                            legend: { display: false },\n                        },\n                        scales: {\n                            y: {\n                                title: { display: true, text: 'Memory (Δ from baseline)' },\n                                ticks: { callback: v =&gt; formatBytes(v) },\n                            },\n                            x: {\n                                title: { display: true, text: 'Time' },\n                                ticks: { maxTicksLimit: 20 },\n                            }\n                        }\n                    }\n                });\n\n                // Load full memory speedscope\n                loadSpeedscopeInIframe(fullSpeedscopeBase64);\n            </script>\n        </body>\n        </html>\n    </t>\n	f	t	2026-11-17 07:22:34.610349	