         if price_unit = 100 and tax 10% price_include -> then the gross_price_unit is 91\\n                        -->\\n                        <ram:GrossPriceProductTradePrice>\\n                            <ram:ChargeAmount t-out=\\"format_monetary(line_vals['gross_price_total_unit'], 2)\\"/>\\n                            <!-- Discount. -->\\n                            <ram:AppliedTradeAllowanceCharge t-if=\\"line.discount\\">\\n                                <ram:ChargeIndicator>\\n                                    <udt:Indicator t-translation=\\"off\\">false</udt:Indicator>\\n                                </ram:ChargeIndicator>\\n                                <ram:ActualAmount t-out=\\"format_monetary(line_vals['price_discount_unit'], 2)\\"/>\\n                            </ram:AppliedTradeAllowanceCharge>\\n                        </ram:GrossPriceProductTradePrice>\\n                        <!-- Line unit price, with discount applied -->\\n                        <ram:NetPriceProductTradePrice>\\n                            <ram:ChargeAmount t-out=\\"format_monetary(line_vals['price_subtotal_unit'], 2)\\"/>\\n                        </ram:NetPriceProductTradePrice>\\n                    </ram:SpecifiedLineTradeAgreement>\\n\\n                    <!-- Quantity. -->\\n                    <ram:SpecifiedLineTradeDelivery>\\n                        <ram:BilledQuantity t-att-unitCode=\\"line_vals.get('unece_uom_code')\\" t-out=\\"line_vals.get('quantity')\\"/>\\n                    </ram:SpecifiedLineTradeDelivery>\\n\\n                    <ram:SpecifiedLineTradeSettlement>\\n                        <t t-foreach=\\"tax_details['tax_details_per_record'][line]['tax_details'].values()\\" t-as=\\"tax_detail_vals\\">\\n                            <ram:ApplicableTradeTax t-if=\\"tax_detail_vals['amount_type'] == 'percent'\\">\\n                                <ram:TypeCode t-translation=\\"off\\">VAT</ram:TypeCode>\\n                                <ram:CategoryCode t-out=\\"tax_detail_vals['tax_category_code']\\"/>\\n                                <ram:RateApplicablePercent t-out=\\"tax_detail_vals['amount']\\"/>\\n                            </ram:ApplicableTradeTax>\\n                        </t>\\n\\n                        <!-- Billing Period -->\\n                        <ram:BillingSpecifiedPeriod t-if=\\"line_vals.get('billing_start') and line_vals.get('billing_end')\\"> \\n                            <ram:StartDateTime>\\n                                <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(line_vals['billing_start'])\\"/>\\n                            </ram:StartDateTime>\\n                            <ram:EndDateTime>\\n                                <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(line_vals['billing_end'])\\"/>\\n                            </ram:EndDateTime>\\n                        </ram:BillingSpecifiedPeriod>\\n\\n                        <!-- Allowance/Charge on the line -->\\n                        <t t-foreach=\\"line_vals.get('allowance_charge_vals_list')\\" t-as=\\"allowance_charge_vals\\">\\n                            <ram:SpecifiedTradeAllowanceCharge>\\n                                <ram:ChargeIndicator>\\n                                    <udt:Indicator t-esc=\\"allowance_charge_vals['indicator']\\"/>\\n                                </ram:ChargeIndicator>\\n                                <ram:ActualAmount t-esc=\\"format_monetary(allowance_charge_vals['amount'], 2)\\"/>\\n                                <ram:ReasonCode t-esc=\\"allowance_charge_vals['reason_code']\\"/>\\n                                <ram:Reason t-esc=\\"allowance_charge_vals['reason']\\"/>\\n                            </ram:SpecifiedTradeAllowanceCharge>\\n                        </t>\\n\\n                        <!-- Subtotal. -->\\n                        <ram:SpecifiedTradeSettlementLineMonetarySummation>\\n                            <ram:LineTotalAmount t-esc=\\"format_monetary(line_vals['line_total_amount'], 2)\\"/>\\n                        </ram:SpecifiedTradeSettlementLineMonetarySummation>\\n\\n                    </ram:SpecifiedLineTradeSettlement>\\n                </ram:IncludedSupplyChainTradeLineItem>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account_edi_ubl_cii.account_invoice_line_facturx_export_22">\n            <t t-set="line" t-value="line_vals['line']"/>\n            <t xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">\n\n                <ram:IncludedSupplyChainTradeLineItem>\n                    <!-- Line number. -->\n                    <ram:AssociatedDocumentLineDocument>\n                        <ram:LineID t-out="line_vals.get('index')"/>\n                    </ram:AssociatedDocumentLineDocument>\n\n                    <!-- Product. -->\n                    <ram:SpecifiedTradeProduct>\n                        <ram:GlobalID schemeID="0160" t-if="line.product_id and line.product_id.barcode" t-out="line.product_id.barcode"/>\n                        <ram:SellerAssignedID t-if="line.product_id and line.product_id.default_code" t-out="line.product_id.default_code"/>\n                        <t t-set="item_name" t-value="line.product_id.name or line.name"/>\n                        <ram:Name t-out="item_name"/>\n                        <ram:Description t-out="line.name" t-if="item_name != line.name"/>\n                    </ram:SpecifiedTradeProduct>\n\n                    <!-- Amounts. -->\n                    <ram:SpecifiedLineTradeAgreement>\n                        <!-- Line information: unit_price\n                        NB: the gross_price_unit should be the price tax excluded!\n                        if price_unit = 100 and tax 10% price_include -> then the gross_price_unit is 91\n                        -->\n                        <ram:GrossPriceProductTradePrice>\n                            <ram:ChargeAmount t-out="format_monetary(line_vals['gross_price_total_unit'], 2)"/>\n                            <!-- Discount. -->\n                            <ram:AppliedTradeAllowanceCharge t-if="line.discount">\n                                <ram:ChargeIndicator>\n                                    <udt:Indicator t-translation="off">false</udt:Indicator>\n                                </ram:ChargeIndicator>\n                                <ram:ActualAmount t-out="format_monetary(line_vals['price_discount_unit'], 2)"/>\n                            </ram:AppliedTradeAllowanceCharge>\n                        </ram:GrossPriceProductTradePrice>\n                        <!-- Line unit price, with discount applied -->\n                        <ram:NetPriceProductTradePrice>\n                            <ram:ChargeAmount t-out="format_monetary(line_vals['price_subtotal_unit'], 2)"/>\n                        </ram:NetPriceProductTradePrice>\n                    </ram:SpecifiedLineTradeAgreement>\n\n                    <!-- Quantity. -->\n                    <ram:SpecifiedLineTradeDelivery>\n                        <ram:BilledQuantity t-att-unitCode="line_vals.get('unece_uom_code')" t-out="line_vals.get('quantity')"/>\n                    </ram:SpecifiedLineTradeDelivery>\n\n                    <ram:SpecifiedLineTradeSettlement>\n                        <t t-foreach="tax_details['tax_details_per_record'][line]['tax_details'].values()" t-as="tax_detail_vals">\n                            <ram:ApplicableTradeTax t-if="tax_detail_vals['amount_type'] == 'percent'">\n                                <ram:TypeCode t-translation="off">VAT</ram:TypeCode>\n                                <ram:CategoryCode t-out="tax_detail_vals['tax_category_code']"/>\n                                <ram:RateApplicablePercent t-out="tax_detail_vals['amount']"/>\n                            </ram:ApplicableTradeTax>\n                        </t>\n\n                        <!-- Billing Period -->\n                        <ram:BillingSpecifiedPeriod t-if="line_vals.get('billing_start') and line_vals.get('billing_end')"> \n                            <ram:StartDateTime>\n                                <udt:DateTimeString format="102" t-out="format_date(line_vals['billing_start'])"/>\n                            </ram:StartDateTime>\n                            <ram:EndDateTime>\n                                <udt:DateTimeString format="102" t-out="format_date(line_vals['billing_end'])"/>\n                            </ram:EndDateTime>\n                        </ram:BillingSpecifiedPeriod>\n\n                        <!-- Allowance/Charge on the line -->\n                        <t t-foreach="line_vals.get('allowance_charge_vals_list')" t-as="allowance_charge_vals">\n                            <ram:SpecifiedTradeAllowanceCharge>\n                                <ram:ChargeIndicator>\n                                    <udt:Indicator t-esc="allowance_charge_vals['indicator']"/>\n                                </ram:ChargeIndicator>\n                                <ram:ActualAmount t-esc="format_monetary(allowance_charge_vals['amount'], 2)"/>\n                                <ram:ReasonCode t-esc="allowance_charge_vals['reason_code']"/>\n                                <ram:Reason t-esc="allowance_charge_vals['reason']"/>\n                            </ram:SpecifiedTradeAllowanceCharge>\n                        </t>\n\n                        <!-- Subtotal. -->\n                        <ram:SpecifiedTradeSettlementLineMonetarySummation>\n                            <ram:LineTotalAmount t-esc="format_monetary(line_vals['line_total_amount'], 2)"/>\n                        </ram:SpecifiedTradeSettlementLineMonetarySummation>\n\n                    </ram:SpecifiedLineTradeSettlement>\n                </ram:IncludedSupplyChainTradeLineItem>\n            </t>\n        </t>\n\n        	f	t	2026-11-17 07:24:23.212332	2026-11-17 07:24:23.212332	f
