ration>\n                                    <ram:ID t-att-schemeID="tax_registration['scheme']" t-out="tax_registration['value']"/>\n                                </ram:SpecifiedTaxRegistration>\n                            </t>\n                        </ram:SellerTradeParty>\n\n                        <!-- Customer. -->\n                        <ram:BuyerTradeParty>\n                            <!-- Address. -->\n                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">\n                                <t t-set="partner" t-value="record.partner_id"/>\n                                <t t-set="specified_legal_organization_val" t-value="buyer_specified_legal_organization"/>\n                            </t>\n\n                            <ram:URIUniversalCommunication t-if="record.partner_id.peppol_eas and record.partner_id.peppol_endpoint">\n                                <ram:URIID t-att-schemeID="record.partner_id.peppol_eas" t-out="record.partner_id.peppol_endpoint"/>\n                            </ram:URIUniversalCommunication>\n\n                            <!-- VAT (BR-CO-09: '/' is not a valid VAT id). -->\n                            <ram:SpecifiedTaxRegistration t-if="record.commercial_partner_id.vat and record.commercial_partner_id.vat not in ['/', 'na', 'NA']">\n                                <ram:ID schemeID="VA" t-out="record.commercial_partner_id.vat"/>\n                            </ram:SpecifiedTaxRegistration>\n                        </ram:BuyerTradeParty>\n\n                        <!-- Reference. -->\n                        <ram:BuyerOrderReferencedDocument>\n                            <!-- "Engagement Juridique" (used by Chorus Pro) -->\n                            <ram:IssuerAssignedID t-out="purchase_order_reference"/>\n                        </ram:BuyerOrderReferencedDocument>\n                        <ram:ContractReferencedDocument>\n                            <!-- "Numéro de Marché" (Us