975	16	\N	1	1	sale.order.form	sale.order	\N	form	sale/views/sale_order_views.xml	primary	{"en_US": "<form string=\\"Sales Order\\" class=\\"o_sale_order\\">\\n            <header>\\n                <button string=\\"Capture Transaction\\" name=\\"payment_action_capture\\" type=\\"object\\" data-hotkey=\\"shift+g\\" class=\\"oe_highlight\\" invisible=\\"not has_authorized_transaction_ids\\"/>\\n                <button string=\\"Void Transaction\\" name=\\"payment_action_void\\" type=\\"object\\" data-hotkey=\\"shift+v\\" confirm=\\"Are you sure you want to void the authorized transaction? This action can't be undone.\\" invisible=\\"not has_authorized_transaction_ids\\"/>\\n                <button string=\\"Create Invoice\\" id=\\"create_invoice\\" name=\\"339\\" type=\\"action\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'to invoice'\\"/>\\n                <button string=\\"Create Invoice\\" id=\\"create_invoice_percentage\\" name=\\"339\\" type=\\"action\\" context=\\"{'default_advance_payment_method': 'percentage'}\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'no' or state != 'sale'\\"/>\\n                <button string=\\"Send\\" id=\\"quotation_send_primary\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'validate_analytic': True, 'check_document_layout': True}\\" class=\\"btn-primary\\" data-hotkey=\\"g\\" invisible=\\"state != 'draft'\\"/>\\n                <button string=\\"Send PRO-FORMA Invoice\\" id=\\"send_proforma_primary\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'proforma': True, 'validate_analytic': True}\\" class=\\"btn-primary\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state != 'draft' or invoice_count &gt;= 1\\"/>\\n                <button string=\\"Confirm\\" id=\\"action_confirm\\" name=\\"action_confirm\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"state != 'sent'\\"/>\\n                <button string=\\"Print\\" name=\\"sale.action_report_saleorder\\" type=\\"action\\" data-hotkey=\\"i\\" invisible=\\"state == 'sale'\\"/>\\n                <button string=\\"Confirm\\" name=\\"action_confirm\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" data-hotkey=\\"q\\" invisible=\\"state != 'draft'\\"/>\\n                <button string=\\"Send PRO-FORMA Invoice\\" id=\\"send_proforma\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'proforma': True, 'validate_analytic': True}\\" invisible=\\"state == 'draft' or invoice_count &gt;= 1\\" groups=\\"sale.group_proforma_sales\\"/>\\n                <button string=\\"Send\\" id=\\"quotation_send\\" name=\\"action_quotation_send\\" type=\\"object\\" context=\\"{'validate_analytic': True, 'check_document_layout': True}\\" data-hotkey=\\"g\\" invisible=\\"state not in ('sent', 'sale')\\"/>\\n\\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\\n                <button string=\\"Unlock\\" name=\\"action_unlock\\" type=\\"object\\" invisible=\\"not locked\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                <button string=\\"Preview\\" name=\\"action_preview_sale_order\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                <button string=\\"Cancel\\" name=\\"action_cancel\\" type=\\"object\\" confirm=\\"Are you sure you want to cancel this order? This may affect related documents or processes.\\" data-hotkey=\\"x\\" invisible=\\"state not in ['draft', 'sent', 'sale'] or not id or locked\\"/>\\n                <button string=\\"Set to Quotation\\" name=\\"action_draft\\" type=\\"object\\" data-hotkey=\\"w\\" invisible=\\"state != 'cancel'\\"/>\\n                <t groups=\\"sale.group_auto_done_setting\\">\\n                    <button string=\\"Lock\\" name=\\"action_lock\\" type=\\"object\\" help=\\"If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver.\\" invisible=\\"locked or state != 'sale'\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                </t>\\n                <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sent,sale\\"/>\\n            </header>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not sale_warning_text\\">\\n                <field name=\\"sale_warning_text\\" class=\\"fw-bold\\"/>\\n            </div>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"partner_credit_warning == ''\\">\\n                <field name=\\"partner_credit_warning\\"/>\\n            </div>\\n            <div class=\\"alert alert-warning p-3 text-center\\" role=\\"alert\\" invisible=\\"state not in ['draft', 'sent'] or not has_archived_products\\">\\n                <span>Warning: This quote contains archived product(s)</span>\\n            </div>\\n            <div class=\\"alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"state != 'draft' or not duplicated_order_ids\\" role=\\"alert\\">\\n                <span>Warning: this order might be a duplicate of</span>\\n                <field name=\\"duplicated_order_ids\\" widget=\\"x2many_buttons\\" string=\\"Duplicated Documents\\"/>\\n            </div>\\n            <sheet>\\n                <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                    <button name=\\"action_view_invoice\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-pencil-square-o\\" invisible=\\"invoice_count == 0\\">\\n                        <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Invoices\\"/>\\n                    </button>\\n                </div>\\n                <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                    <i class=\\"fa fa-lock\\"/>\\n                    Locked\\n                </div>\\n                <div class=\\"oe_title\\">\\n                    <h1>\\n                        <field name=\\"name\\" readonly=\\"1\\"/>\\n                    </h1>\\n                </div>\\n                <group name=\\"sale_header\\">\\n                    <group name=\\"partner_details\\">\\n                        <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}\\" placeholder=\\"Type to find a customer...\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <field name=\\"partner_invoice_id\\" groups=\\"account.group_delivery_invoice_address\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_type': 'invoice', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                        <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" options=\\"{'no_quick_create': True}\\" context=\\"{'default_type': 'delivery', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                    </group>\\n                    <group name=\\"order_details\\">\\n                        <field name=\\"validity_date\\" invisible=\\"state == 'sale'\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\">\\n                            <label for=\\"date_order\\" string=\\"Quotation Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" invisible=\\"state in ['draft', 'sent']\\">\\n                            <label for=\\"date_order\\" string=\\"Order Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" invisible=\\"state in ['draft', 'sent']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <field name=\\"show_update_pricelist\\" invisible=\\"1\\"/>\\n                        <label for=\\"pricelist_id\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not has_active_pricelist\\"/>\\n                        <div groups=\\"product.group_product_pricelist\\" class=\\"o_row\\" invisible=\\"not has_active_pricelist\\">\\n                            <field name=\\"pricelist_id\\" options=\\"{'no_open': True, 'no_create': True}\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                            <button name=\\"action_update_prices\\" type=\\"object\\" string=\\"Update Prices\\" help=\\"Recompute all prices based on this pricelist\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"This will update the unit price of all products based on the new pricelist.\\" invisible=\\"not show_update_pricelist or state in ['sale', 'cancel']\\"/>\\n                        </div>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"pricelist_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'sale']\\" groups=\\"!product.group_product_pricelist\\"/>\\n                        <field name=\\"payment_term_id\\" placeholder=\\"Immediate\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                    </group>\\n                </group>\\n                <notebook>\\n                    <page string=\\"Order Lines\\" name=\\"order_lines\\">\\n                        <field name=\\"order_line\\" widget=\\"sol_o2m\\" mode=\\"list,kanban\\" readonly=\\"state == 'cancel' or locked\\" aggregated_fields=\\"price_subtotal,price_total\\" options=\\"{'hide_composition': True, 'hide_prices': True, 'subsections': True}\\">\\n                            <form>\\n                                <field name=\\"technical_price_unit\\" invisible=\\"1\\"/>\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <!-- Display_type must be specified as non readonly (which would be the case with the default field added by ORM) -->\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"product_id\\"/>\\n                                        <div class=\\"d-flex align-items-baseline\\">\\n                                            <span class=\\"fa fa-exclamation-triangle text-warning me-1\\" title=\\"This product is archived\\" invisible=\\"state not in ['draft', 'sent'] or not is_product_archived\\"/>\\n                                            <field name=\\"product_id\\" context=\\"{                                                     'default_uom_id': product_uom_id,                                                     'partner_id': parent.partner_id,                                                 }\\" readonly=\\"not product_updatable\\" required=\\"not display_type and not is_downpayment\\" force_save=\\"1\\" widget=\\"many2one_barcode\\"/>\\n                                        </div>\\n                                        <label for=\\"product_uom_qty\\"/>\\n                                        <div class=\\"o_row\\" name=\\"ordered_qty\\">\\n                                            <field name=\\"product_uom_qty\\"/>\\n                                            <field name=\\"product_uom_id\\" force_save=\\"1\\" groups=\\"uom.group_uom\\" class=\\"oe_no_button\\" widget=\\"many2one_uom\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type and not is_downpayment\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_delivered\\" string=\\"Delivered\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"delivered_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_delivered\\" readonly=\\"qty_delivered_method != 'manual'\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_invoiced\\" string=\\"Invoiced\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"invoiced_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_invoiced\\"/>\\n                                        </div>\\n                                        <field name=\\"price_unit\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" context=\\"{'search_view_ref': 'account.account_tax_view_search'}\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                        <t groups=\\"sale.group_discount_per_so_line\\">\\n                                            <label for=\\"discount\\"/>\\n                                            <div name=\\"discount\\">\\n                                                <field name=\\"discount\\" class=\\"oe_inline\\"/> %\\n                                            </div>\\n                                        </t>\\n                                    </group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"customer_lead\\"/>\\n                                        <div name=\\"lead\\">\\n                                            <field name=\\"customer_lead\\" class=\\"oe_inline\\" readonly=\\"product_type != 'consu'\\"/> days\\n                                        </div>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order'}\\"/>\\n                                    </group>\\n                                </group>\\n                                <label for=\\"name\\" string=\\"Description\\" invisible=\\"display_type\\"/>\\n                                <label for=\\"name\\" string=\\"Section Name (eg. Products, Services)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                <label for=\\"name\\" string=\\"Subsection Name\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                <field name=\\"name\\"/>\\n                                <group>\\n                                    <field name=\\"collapse_composition\\" invisible=\\"display_type not in ['line_section', 'line_subsection']\\" readonly=\\"1\\"/>\\n                                    <field name=\\"collapse_prices\\" invisible=\\"display_type not in ['line_section', 'line_subsection']\\" readonly=\\"1\\"/>\\n                                </group>\\n                                <div name=\\"invoice_lines\\" groups=\\"base.group_no_one\\" invisible=\\"display_type\\">\\n                                    <label for=\\"invoice_lines\\"/>\\n                                    <field name=\\"invoice_lines\\"/>\\n                                </div>\\n                            </form>\\n                            <list string=\\"Sales Order Lines\\" editable=\\"bottom\\" decoration-warning=\\"(state in ['draft', 'sent'] and is_product_archived) or sale_line_warn_msg\\">\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Add a product\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Add a section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Add a note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button string=\\"Catalog\\" name=\\"action_add_from_catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n\\n                                <!-- Non readonly invisible fields, must be specified manually, because fields added automatically by the ORM\\n                                    are readonly, widgets fieldDependencies too -->\\n                                <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_custom_attribute_value_ids\\" column_invisible=\\"1\\">\\n                                    <list>\\n                                        <field name=\\"custom_product_template_attribute_value_id\\"/>\\n                                        <field name=\\"custom_value\\"/>\\n                                    </list>\\n                                </field>\\n                                <field name=\\"product_no_variant_attribute_value_ids\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"technical_price_unit\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_line_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"combo_item_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"selected_combo_items\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"linked_virtual_id\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_composition\\" column_invisible=\\"1\\"/>\\n                                <field name=\\"collapse_prices\\" column_invisible=\\"1\\"/>\\n\\n                                <!-- Currency, needed for monetary widgets to display the currency symbol -->\\n                                <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n\\n                                <!-- Standard fields -->\\n                                <field name=\\"sequence\\" invisible=\\"combo_item_id\\" widget=\\"handle\\"/>\\n                                <field name=\\"product_id\\" string=\\"Product Variant\\" readonly=\\"not product_updatable\\" required=\\"not display_type and not is_downpayment\\" force_save=\\"1\\" context=\\"{                                         'default_lst_price': price_unit,                                         'default_uom_id': product_uom_id,                                         'partner_id': parent.partner_id,                                     }\\" options=\\"{                                         'show_label_warning': True                                     }\\" optional=\\"hide\\" widget=\\"sol_product_many2one\\"/>\\n                                <field name=\\"product_template_id\\" string=\\"Product\\" readonly=\\"id and not product_updatable\\" required=\\"not display_type and not is_downpayment\\" context=\\"{                                         'default_list_price': price_unit,                                         'default_uom_id': product_uom_id,                                         'partner_id': parent.partner_id,                                     }\\" options=\\"{                                         'show_label_warning': True                                     }\\" optional=\\"show\\" widget=\\"sol_product_many2one\\" placeholder=\\"Type to find a product...\\"/>\\n                                <field name=\\"name\\" widget=\\"sol_text\\" optional=\\"show\\"/>\\n                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" options=\\"{                                         'product_field': 'product_id',                                         'business_domain': 'sale_order',                                         'amount_field': 'price_subtotal',                                     }\\" optional=\\"hide\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                <field name=\\"product_uom_qty\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" readonly=\\"is_downpayment\\"/>\\n                                <field name=\\"qty_delivered\\" string=\\"Delivered\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" column_invisible=\\"parent.state != 'sale'\\" readonly=\\"qty_delivered_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"qty_invoiced\\" string=\\"Invoiced\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" column_invisible=\\"parent.state != 'sale'\\" optional=\\"show\\"/>\\n                                <field name=\\"product_uom_id\\" force_save=\\"1\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type and not is_downpayment\\" widget=\\"many2one_uom\\" groups=\\"uom.group_uom\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\" width=\\"60px\\" optional=\\"show\\"/>\\n                                <field name=\\"customer_lead\\" optional=\\"hide\\" width=\\"80px\\" readonly=\\"parent.state not in ['draft', 'sent', 'sale'] or is_downpayment or product_type != 'consu'\\"/>\\n                                <field name=\\"price_unit\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" context=\\"{'active_test': True}\\" readonly=\\"qty_invoiced &gt; 0 or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"discount\\" string=\\"Disc.%\\" groups=\\"sale.group_discount_per_so_line\\" width=\\"50px\\" optional=\\"show\\"/>\\n                                <field name=\\"price_subtotal\\" string=\\"Amount\\" column_invisible=\\"parent.company_price_include == 'tax_included'\\" invisible=\\"is_downpayment\\"/>\\n                                <field name=\\"price_total\\" string=\\"Amount\\" column_invisible=\\"parent.company_price_include == 'tax_excluded'\\" invisible=\\"is_downpayment\\"/>\\n                                <!-- Optional amounts columns -->\\n                                <field name=\\"price_total\\" string=\\"Tax Incl.\\" column_invisible=\\"parent.company_price_include == 'tax_included'\\" invisible=\\"is_downpayment\\" optional=\\"hide\\"/>\\n                                <field name=\\"price_subtotal\\" string=\\"Tax Excl.\\" column_invisible=\\"parent.company_price_include == 'tax_excluded'\\" invisible=\\"is_downpayment\\" optional=\\"hide\\"/>\\n                            </list>\\n                            <kanban class=\\"o_kanban_mobile\\">\\n                                <field name=\\"display_type\\"/>\\n                                <field name=\\"currency_id\\"/>\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Add product\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Add section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Add note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button string=\\"Catalog\\" name=\\"action_add_from_catalog\\" type=\\"object\\" class=\\"btn-secondary\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n                                <templates>\\n                                    <t t-name=\\"card\\" class=\\"row g-0 ps-0 pe-0\\">\\n                                        <t t-if=\\"!record.display_type.raw_value\\">\\n                                            <aside class=\\"col-2 p-1\\">\\n                                                <span t-att-title=\\"record.product_id.value\\">\\n                                                    <field name=\\"product_id\\" widget=\\"image\\" options=\\"{'preview_image': 'image_128', 'img_class': 'object-fit-contain w-100'}\\"/>\\n                                                </span>\\n                                            </aside>\\n                                            <main class=\\"col\\">\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col\\">\\n                                                        <span class=\\"fa fa-exclamation-triangle text-warning me-1\\" title=\\"This product is archived\\" invisible=\\"state not in ['draft', 'sent'] or not is_product_archived\\"/>\\n                                                        <field name=\\"product_id\\" class=\\"fw-bold\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-auto\\">\\n                                                        <field name=\\"price_subtotal\\" class=\\"fw-bolder float-end pe-1\\" widget=\\"monetary\\"/>\\n                                                    </div>\\n                                                </div>\\n                                                <div class=\\"text-muted\\">\\n                                                    Quantity:\\n                                                    <field name=\\"product_uom_qty\\"/> <field name=\\"product_uom_id\\"/>\\n                                                </div>\\n                                                <div class=\\"text-muted\\">\\n                                                    Unit Price:\\n                                                    <field name=\\"price_unit\\"/>\\n                                                </div>\\n                                                <t t-if=\\"record.discount?.raw_value\\">\\n                                                    <div class=\\"text-muted\\">\\n                                                        Discount:\\n                                                        <field name=\\"discount\\"/>%\\n                                                    </div>\\n                                                </t>\\n                                            </main>\\n                                        </t>\\n                                        <t t-if=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                            <div t-att-class=\\"{                                                 'fw-bolder': record.display_type.raw_value === 'line_section',                                                 'fw-bold': record.display_type.raw_value === 'line_subsection',                                                 'fst-italic': record.display_type.raw_value === 'line_note',                                             }\\">\\n                                                <field name=\\"name\\"/>\\n                                            </div>\\n                                        </t>\\n                                    </t>\\n                                </templates>\\n                            </kanban>\\n                        </field>\\n                        <div class=\\"float-end d-flex d-print-none gap-1 mb-2\\" name=\\"so_button_below_order_lines\\">\\n                            <button string=\\"Discount\\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary\\" groups=\\"sale.group_discount_per_so_line\\" invisible=\\"locked or state == 'cancel'\\"/>\\n                            <button string=\\"Discounts\\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary\\" groups=\\"sale.group_discount_per_so_line\\" disabled=\\"1\\" invisible=\\"not (locked or state == 'cancel')\\"/>\\n                        </div>\\n                        <group name=\\"note_group\\" col=\\"6\\" class=\\"mt-2 mt-md-0\\">\\n                            <group colspan=\\"4\\" class=\\"order-1 order-lg-0\\">\\n                                <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Terms and conditions...\\"/>\\n                            </group>\\n                            <group class=\\"oe_subtotal_footer d-flex order-0 order-lg-1 flex-column gap-0 gap-sm-3\\" colspan=\\"2\\" name=\\"sale_total\\">\\n                                <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" readonly=\\"1\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                    <page string=\\"Other Info\\" name=\\"other_information\\">\\n                        <group>\\n                            <group name=\\"sales_person\\" string=\\"Sales\\">\\n                                <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                <field name=\\"team_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"company_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_company\\"/>\\n                                <field name=\\"require_signature\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                <label for=\\"require_payment\\"/>\\n                                <div id=\\"require_payment\\">\\n                                    <field name=\\"require_payment\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                    <span class=\\"mx-3\\" invisible=\\"not require_payment\\">of</span>\\n                                    <field name=\\"prepayment_percent\\" readonly=\\"state in ['cancel', 'sale']\\" invisible=\\"not require_payment\\" widget=\\"percentage\\" style=\\"width: 3rem\\"/>\\n                                </div>\\n                                <field name=\\"reference\\" readonly=\\"1\\" invisible=\\"not reference\\"/>\\n                                <field name=\\"client_order_ref\\"/>\\n                                <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'no_create_edit': True}\\"/>\\n                            </group>\\n                            <group name=\\"sale_info\\" string=\\"Invoicing\\">\\n                                <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n                                <label for=\\"fiscal_position_id\\"/>\\n                                <div class=\\"o_row\\">\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\"/>\\n                                    <button string=\\"Update Taxes\\" name=\\"action_update_taxes\\" type=\\"object\\" help=\\"Recompute all taxes based on this fiscal position\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"This will update all taxes based on the currently selected fiscal position.\\" invisible=\\"not show_update_fpos or state in ['sale', 'cancel']\\"/>\\n                                </div>\\n                                <field name=\\"preferred_payment_method_line_id\\"/>\\n                                <field name=\\"partner_invoice_id\\" groups=\\"!account.group_delivery_invoice_address\\" invisible=\\"1\\"/>\\n                                <field name=\\"journal_id\\" groups=\\"base.group_no_one\\" readonly=\\"invoice_count != 0 and state == 'sale'\\"/>\\n                                <field name=\\"invoice_status\\" invisible=\\"state != 'sale'\\" groups=\\"base.group_no_one\\"/>\\n                                <!-- test_event_configurator -->\\n                                <field name=\\"invoice_status\\" invisible=\\"1\\" groups=\\"!base.group_no_one\\"/>\\n                            </group>\\n                            <group name=\\"sale_shipping\\" string=\\"Shipping\\">\\n                                <label for=\\"commitment_date\\" string=\\"Delivery Date\\"/>\\n                                <div name=\\"commitment_date_div\\" class=\\"o_row\\">\\n                                    <field name=\\"commitment_date\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                                    <span name=\\"expected_date_span\\" invisible=\\"not expected_date\\" class=\\"text-muted\\">Expected: <field name=\\"expected_date\\" class=\\"oe_inline\\"/></span>\\n                                </div>\\n                            </group>\\n                            <group name=\\"sale_reporting\\" string=\\"Tracking\\">\\n                                <field name=\\"origin\\"/>\\n                                <field name=\\"campaign_id\\" options=\\"{'create_name_field': 'title'}\\"/>\\n                                <field name=\\"medium_id\\"/>\\n                                <field name=\\"source_id\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                    <page groups=\\"base.group_no_one\\" string=\\"Customer Signature\\" name=\\"customer_signature\\" invisible=\\"1\\">\\n                        <group>\\n                            <field name=\\"signed_by\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signed_on\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signature\\" widget=\\"image\\"/>\\n                        </group>\\n                    </page>\\n                </notebook>\\n            </sheet>\\n            <chatter/>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Sales Order" class="o_sale_order">\n            <header>\n                <button string="Capture Transaction" name="payment_action_capture" type="object" data-hotkey="shift+g" class="oe_highlight" invisible="not has_authorized_transaction_ids"/>\n                <button string="Void Transaction" name="payment_action_void" type="object" data-hotkey="shift+v" confirm="Are you sure you want to void the authorized transaction? This action can't be undone." invisible="not has_authorized_transaction_ids"/>\n                <button string="Create Invoice" id="create_invoice" name="339" type="action" class="btn-primary" data-hotkey="q" invisible="invoice_status != 'to invoice'"/>\n                <button string="Create Invoice" id="create_invoice_percentage" name="339" type="action" context="{'default_advance_payment_method': 'percentage'}" data-hotkey="q" invisible="invoice_status != 'no' or state != 'sale'"/>\n                <button string="Send" id="quotation_send_primary" name="action_quotation_send" type="object" context="{'validate_analytic': True, 'check_document_layout': True}" class="btn-primary" data-hotkey="g" invisible="state != 'draft'"/>\n                <button string="Send PRO-FORMA Invoice" id="send_proforma_primary" name="action_quotation_send" type="object" context="{'proforma': True, 'validate_analytic': True}" class="btn-primary" groups="sale.group_proforma_sales" invisible="state != 'draft' or invoice_count &gt;= 1"/>\n                <button string="Confirm" id="action_confirm" name="action_confirm" type="object" context="{'validate_analytic': True}" class="btn-primary" data-hotkey="q" invisible="state != 'sent'"/>\n                <button string="Print" name="sale.action_report_saleorder" type="action" data-hotkey="i" invisible="state == 'sale'"/>\n                <button string="Confirm" name="action_confirm" type="object" context="{'validate_analytic': True}" data-hotkey="q" invisible="state != 'draft'"/>\n                <button string="Send PRO-FORMA Invoice" id="send_proforma" name="action_quotation_send" type="object" context="{'proforma': True, 'validate_analytic': True}" invisible="state == 'draft' or invoice_count &gt;= 1" groups="sale.group_proforma_sales"/>\n                <button string="Send" id="quotation_send" name="action_quotation_send" type="object" context="{'validate_analytic': True, 'check_document_layout': True}" data-hotkey="g" invisible="state not in ('sent', 'sale')"/>\n\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\n                <button string="Unlock" name="action_unlock" type="object" invisible="not locked" groups="sales_team.group_sale_manager"/>\n                <button string="Preview" name="action_preview_sale_order" type="object" class="btn-secondary"/>\n                <button string="Cancel" name="action_cancel" type="object" confirm="Are you sure you want to cancel this order? This may affect related documents or processes." data-hotkey="x" invisible="state not in ['draft', 'sent', 'sale'] or not id or locked"/>\n                <button string="Set to Quotation" name="action_draft" type="object" data-hotkey="w" invisible="state != 'cancel'"/>\n                <t groups="sale.group_auto_done_setting">\n                    <button string="Lock" name="action_lock" type="object" help="If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver." invisible="locked or state != 'sale'" groups="sales_team.group_sale_manager"/>\n                </t>\n                <field name="state" widget="statusbar" statusbar_visible="draft,sent,sale"/>\n            </header>\n            <div class="alert alert-warning" role="alert" invisible="not sale_warning_text">\n                <field name="sale_warning_text" class="fw-bold"/>\n            </div>\n            <div class="alert alert-warning" role="alert" invisible="partner_credit_warning == ''">\n                <field name="partner_credit_warning"/>\n            </div>\n            <div class="alert alert-warning p-3 text-center" role="alert" invisible="state not in ['draft', 'sent'] or not has_archived_products">\n                <span>Warning: This quote contains archived product(s)</span>\n            </div>\n            <div class="alert alert-warning w-100 d-flex align-items-center gap-1" invisible="state != 'draft' or not duplicated_order_ids" role="alert">\n                <span>Warning: this order might be a duplicate of</span>\n                <field name="duplicated_order_ids" widget="x2many_buttons" string="Duplicated Documents"/>\n            </div>\n            <sheet>\n                <div class="oe_button_box" name="button_box">\n                    <button name="action_view_invoice" type="object" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0">\n                        <field name="invoice_count" widget="statinfo" string="Invoices"/>\n                    </button>\n                </div>\n                <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                    <i class="fa fa-lock"/>\n                    Locked\n                </div>\n                <div class="oe_title">\n                    <h1>\n                        <field name="name" readonly="1"/>\n                    </h1>\n                </div>\n                <group name="sale_header">\n                    <group name="partner_details">\n                        <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}" placeholder="Type to find a customer..." readonly="state in ['cancel', 'sale']"/>\n                        <field name="partner_invoice_id" groups="account.group_delivery_invoice_address" options="{'no_quick_create': True}" context="{'default_type': 'invoice', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}" readonly="state == 'cancel' or locked"/>\n                        <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" options="{'no_quick_create': True}" context="{'default_type': 'delivery', 'show_address': False, 'show_vat': False, 'default_parent_id': partner_id}" readonly="state == 'cancel' or locked"/>\n                    </group>\n                    <group name="order_details">\n                        <field name="validity_date" invisible="state == 'sale'" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" groups="base.group_no_one" invisible="state in ['sale', 'cancel']">\n                            <label for="date_order" string="Quotation Date"/>\n                        </div>\n                        <field name="date_order" nolabel="1" groups="base.group_no_one" invisible="state in ['sale', 'cancel']" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" invisible="state in ['draft', 'sent']">\n                            <label for="date_order" string="Order Date"/>\n                        </div>\n                        <field name="date_order" nolabel="1" invisible="state in ['draft', 'sent']" readonly="state in ['cancel', 'sale']"/>\n                        <field name="show_update_pricelist" invisible="1"/>\n                        <label for="pricelist_id" groups="product.group_product_pricelist" invisible="not has_active_pricelist"/>\n                        <div groups="product.group_product_pricelist" class="o_row" invisible="not has_active_pricelist">\n                            <field name="pricelist_id" options="{'no_open': True, 'no_create': True}" readonly="state in ['cancel', 'sale']"/>\n                            <button name="action_update_prices" type="object" string="Update Prices" help="Recompute all prices based on this pricelist" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update the unit price of all products based on the new pricelist." invisible="not show_update_pricelist or state in ['sale', 'cancel']"/>\n                        </div>\n                        <field name="currency_id" invisible="1"/>\n                        <field name="pricelist_id" invisible="1" readonly="state in ['cancel', 'sale']" groups="!product.group_product_pricelist"/>\n                        <field name="payment_term_id" placeholder="Immediate" options="{'no_open': True, 'no_create': True}"/>\n                    </group>\n                </group>\n                <notebook>\n                    <page string="Order Lines" name="order_lines">\n                        <field name="order_line" widget="sol_o2m" mode="list,kanban" readonly="state == 'cancel' or locked" aggregated_fields="price_subtotal,price_total" options="{'hide_composition': True, 'hide_prices': True, 'subsections': True}">\n                            <form>\n                                <field name="technical_price_unit" invisible="1"/>\n                                <!--\n                                    We need the sequence field to be here for new lines to be added at the correct position.\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\n                                -->\n                                <field name="sequence" invisible="1"/>\n                                <!-- Display_type must be specified as non readonly (which would be the case with the default field added by ORM) -->\n                                <field name="display_type" invisible="1"/>\n                                <group>\n                                    <group invisible="display_type">\n                                        <label for="product_id"/>\n                                        <div class="d-flex align-items-baseline">\n                                            <span class="fa fa-exclamation-triangle text-warning me-1" title="This product is archived" invisible="state not in ['draft', 'sent'] or not is_product_archived"/>\n                                            <field name="product_id" context="{                                                     'default_uom_id': product_uom_id,                                                     'partner_id': parent.partner_id,                                                 }" readonly="not product_updatable" required="not display_type and not is_downpayment" force_save="1" widget="many2one_barcode"/>\n                                        </div>\n                                        <label for="product_uom_qty"/>\n                                        <div class="o_row" name="ordered_qty">\n                                            <field name="product_uom_qty"/>\n                                            <field name="product_uom_id" force_save="1" groups="uom.group_uom" class="oe_no_button" widget="many2one_uom" readonly="product_uom_readonly" required="not display_type and not is_downpayment"/>\n                                        </div>\n                                        <label for="qty_delivered" string="Delivered" invisible="parent.state != 'sale'"/>\n                                        <div name="delivered_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_delivered" readonly="qty_delivered_method != 'manual'"/>\n                                        </div>\n                                        <label for="qty_invoiced" string="Invoiced" invisible="parent.state != 'sale'"/>\n                                        <div name="invoiced_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_invoiced"/>\n                                        </div>\n                                        <field name="price_unit"/>\n                                        <field name="tax_ids" widget="many2many_tax_tags" options="{'no_create': True}" context="{'search_view_ref': 'account.account_tax_view_search'}" readonly="qty_invoiced &gt; 0"/>\n                                        <t groups="sale.group_discount_per_so_line">\n                                            <label for="discount"/>\n                                            <div name="discount">\n                                                <field name="discount" class="oe_inline"/> %\n                                            </div>\n                                        </t>\n                                    </group>\n                                    <group invisible="display_type">\n                                        <label for="customer_lead"/>\n                                        <div name="lead">\n                                            <field name="customer_lead" class="oe_inline" readonly="product_type != 'consu'"/> days\n                                        </div>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic